
.phone-container {
  width: 100%;
  max-width: 380px;
  margin: 0 auto;
}

.phone-shell {
  background: var(--phone-bg);
  border: 2px solid var(--phone-border);
  border-radius: 24px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow:
    0 0 30px rgba(0, 0, 0, 0.5),
    0 0 60px rgba(0, 212, 170, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

// 顶部状态栏
.phone-statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  background: var(--phone-bg);
  font-size: 11px;
  color: var(--phone-text-dim);
  border-bottom: 1px solid var(--phone-border);
}

.time-display {
  font-weight: 600;
  color: var(--phone-text);
  font-family: var(--font-mono);
}

.notch {
  width: 80px;
  height: 18px;
  background: #000;
  border-radius: 0 0 12px 12px;
  border: 1px solid var(--phone-border);
  border-top: none;
}

.status-icons {
  display: flex;
  gap: 4px;
  font-size: 10px;
}

// 内容区
.phone-screen {
  flex: 1;
  min-height: 380px;
  max-height: 520px;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0;
  background: var(--phone-surface);
}

// 返回导航
.nav-back {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  background: var(--phone-bg);
  border-bottom: 1px solid var(--phone-border);
  cursor: pointer;
  color: var(--phone-accent);
  font-size: 13px;
  font-weight: 600;
  transition: background 0.2s;

  &:hover {
    background: var(--phone-card);
  }
}

.back-arrow {
  font-size: 20px;
  line-height: 1;
}

// 底部导航
.phone-navbar {
  display: flex;
  background: var(--phone-bg);
  border-top: 1px solid var(--phone-border);
  padding: 6px 0 8px;
}

.nav-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border: none;
  background: transparent;
  color: var(--phone-text-muted);
  cursor: pointer;
  padding: 4px 0;
  transition: all 0.2s;
  font-size: 10px;

  &:hover {
    color: var(--phone-text-dim);
  }

  &.active {
    color: var(--phone-accent);
    .nav-icon {
      transform: scale(1.15);
    }
  }
}

.nav-icon {
  font-size: 18px;
  transition: transform 0.2s;
}

.nav-label {
  font-weight: 500;
}
