
.contact-detail {
  padding: 12px;
}

.detail-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  background: linear-gradient(135deg, var(--phone-card), var(--phone-bg));
  border: 1px solid var(--phone-border);
  border-radius: 12px;
  margin-bottom: 12px;
}
.detail-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--phone-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  border: 2px solid var(--phone-accent);
  flex-shrink: 0;
}
.detail-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--phone-text);
}
.detail-age {
  font-size: 12px;
  color: var(--phone-text-dim);
  margin-top: 2px;
}
.detail-badges {
  display: flex;
  gap: 6px;
  margin-top: 6px;
}
.badge {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 600;
}
.badge-resident {
  background: var(--phone-accent-dim);
  color: var(--phone-accent);
}
.badge-wechat {
  background: rgba(16, 185, 129, 0.15);
  color: var(--phone-health);
}

.info-cards {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}
.info-card {
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
  padding: 10px 12px;
}
.card-label {
  font-size: 10px;
  color: var(--phone-text-muted);
  font-weight: 600;
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 4px;
}
.card-icon {
  font-size: 12px;
}
.card-value {
  font-size: 12px;
  color: var(--phone-text);
  line-height: 1.5;
  &.no-ability {
    color: var(--phone-text-muted);
    font-style: italic;
  }
  &.interaction {
    font-size: 11px;
    color: var(--phone-text-dim);
  }
}

// 聊天区
.chat-section {
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
  padding: 12px;
}

// 聊天记录
.chat-history {
  margin-bottom: 12px;
}
.history-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--phone-text);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.history-count {
  margin-left: auto;
  font-size: 9px;
  color: var(--phone-text-muted);
  padding: 1px 6px;
  background: var(--phone-bg);
  border-radius: 6px;
}
.history-list {
  max-height: 200px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-right: 4px;
}
.history-msg {
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--phone-bg);
  border: 1px solid var(--phone-border);
  &.msg-self {
    border-color: var(--phone-accent-dim);
    background: rgba(0, 212, 170, 0.05);
  }
}
.msg-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2px;
}
.msg-sender {
  font-size: 10px;
  font-weight: 600;
  color: var(--phone-accent);
}
.msg-self .msg-sender {
  color: var(--phone-text);
}
.msg-time {
  font-size: 9px;
  color: var(--phone-text-muted);
}
.msg-body {
  font-size: 11px;
  color: var(--phone-text-dim);
  line-height: 1.5;
}
.history-empty {
  text-align: center;
  color: var(--phone-text-muted);
  font-size: 10px;
  font-style: italic;
  padding: 12px;
}

// 发送区
.send-area {
  margin-bottom: 8px;
}
.send-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--phone-text);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.input-row {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}
.chat-input {
  flex: 1;
  background: var(--phone-bg);
  border: 1px solid var(--phone-border);
  border-radius: 8px;
  padding: 8px 10px;
  color: var(--phone-text);
  font-size: 12px;
  font-family: inherit;
  resize: none;
  outline: none;
  &:focus {
    border-color: var(--phone-accent);
  }
  &::placeholder {
    color: var(--phone-text-muted);
  }
}
.send-btn {
  padding: 8px 16px;
  background: var(--phone-accent);
  color: var(--phone-bg);
  border: none;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s;
  &:hover:not(.disabled) {
    transform: scale(1.05);
    box-shadow: var(--phone-glow);
  }
  &.disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }
}
.send-hint {
  margin-top: 6px;
  font-size: 9px;
  color: var(--phone-text-muted);
  font-style: italic;
}

// 待发送提示
.pending-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  background: rgba(255, 165, 2, 0.1);
  border: 1px solid rgba(255, 165, 2, 0.3);
  border-radius: var(--phone-radius);
  margin-top: 8px;
}
.pending-icon {
  font-size: 14px;
}
.pending-text {
  flex: 1;
  font-size: 10px;
  color: var(--phone-warning);
  font-weight: 600;
}
.pending-clear {
  padding: 3px 8px;
  background: transparent;
  border: 1px solid var(--phone-warning);
  border-radius: 4px;
  color: var(--phone-warning);
  font-size: 9px;
  cursor: pointer;
  font-weight: 600;
  &:hover {
    background: rgba(255, 165, 2, 0.15);
  }
}

// 未加微信
.no-wechat-hint {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px;
  background: var(--phone-card);
  border: 1px dashed var(--phone-border);
  border-radius: var(--phone-radius);
}
.hint-icon {
  font-size: 20px;
}
.hint-text {
  font-size: 11px;
  color: var(--phone-text-dim);
}
