
.warehouse {
  padding: 12px;
}

.section-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--phone-border);
}

.section-icon {
  font-size: 16px;
}

.section-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--phone-text);
  flex: 1;
}

.item-count {
  font-size: 10px;
  color: var(--phone-text-dim);
  padding: 2px 8px;
  background: var(--phone-card);
  border-radius: 8px;
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}

.item-card {
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
  padding: 10px 12px;
  transition: all 0.2s;

  &.low-stock {
    border-color: var(--phone-warning);
    .item-name {
      color: var(--phone-warning);
    }
  }

  &.depleted {
    border-color: var(--phone-danger);
    opacity: 0.6;
    .item-name {
      color: var(--phone-danger);
      text-decoration: line-through;
    }
  }
}

.item-main {
  display: flex;
  align-items: center;
  gap: 10px;
}

.item-icon {
  font-size: 20px;
}

.item-info {
  flex: 1;
}

.item-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--phone-text);
  display: block;
}

.item-meta {
  display: flex;
  gap: 8px;
  margin-top: 2px;
}

.item-quantity {
  font-size: 10px;
  color: var(--phone-text-dim);
  font-weight: 500;
}

.item-consume {
  font-size: 10px;
  color: var(--phone-danger);
  font-weight: 600;
}

.days-left {
  text-align: center;
  min-width: 36px;
}

.days-num {
  display: block;
  font-size: 16px;
  font-weight: 700;
  color: var(--phone-text);
  font-family: var(--font-mono);
}

.days-label {
  display: block;
  font-size: 9px;
  color: var(--phone-text-muted);
}

.stock-bar {
  height: 3px;
  background: var(--phone-border);
  border-radius: 2px;
  margin-top: 8px;
  overflow: hidden;
}

.stock-fill {
  height: 100%;
  border-radius: 2px;
  transition: width 0.3s;

  &.safe {
    background: var(--phone-health);
  }
  &.warning {
    background: var(--phone-warning);
  }
  &.critical {
    background: var(--phone-danger);
    animation: flash 1s infinite;
  }
}

@keyframes flash {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.daily-summary {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  background: var(--phone-bg);
  border-radius: var(--phone-radius);
  border: 1px dashed var(--phone-border);
}

.summary-icon {
  font-size: 14px;
}

.summary-text {
  font-size: 10px;
  color: var(--phone-text-dim);
}
