
.safehouse-map {
  padding: 12px;
}

.floor-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 12px;
  background: var(--phone-bg);
  border-radius: 8px;
  padding: 3px;
}

.floor-tab {
  flex: 1;
  padding: 8px;
  border: none;
  background: transparent;
  color: var(--phone-text-dim);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border-radius: 6px;
  transition: all 0.2s;

  &:hover {
    color: var(--phone-text);
  }

  &.active {
    background: var(--phone-accent);
    color: var(--phone-bg);
  }
}

.safehouse-info {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
  padding: 8px 12px;
  background: var(--phone-card);
  border-radius: var(--phone-radius);
  border: 1px solid var(--phone-border);
}

.level-badge {
  padding: 2px 8px;
  background: var(--phone-accent);
  color: var(--phone-bg);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
}

.level-text {
  font-size: 12px;
  color: var(--phone-text-dim);
}

.room-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.room-card {
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
  padding: 10px;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    border-color: var(--phone-accent);
    box-shadow: var(--phone-glow);
  }

  &.occupied {
    border-left: 3px solid var(--phone-accent);
  }

  &.expanded {
    grid-column: 1 / -1;
  }
}

.room-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.room-icon {
  font-size: 16px;
}

.room-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--phone-text);
}

.room-npc {
  display: flex;
  align-items: center;
  gap: 4px;
}

.npc-dot {
  width: 6px;
  height: 6px;
  background: var(--phone-accent);
  border-radius: 50%;
  animation: blink 1.5s infinite;
}

@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

.npc-name {
  font-size: 10px;
  color: var(--phone-accent);
  font-weight: 500;
}

.room-empty {
  font-size: 10px;
  color: var(--phone-text-muted);
  font-style: italic;
}

.room-detail {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--phone-border);
}

.npc-detail {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.detail-label {
  font-size: 10px;
  color: var(--phone-text-muted);
}

.detail-value {
  font-size: 10px;
  color: var(--phone-text);
  text-align: right;
  max-width: 60%;
}

.empty-detail {
  text-align: center;
  color: var(--phone-text-muted);
  font-size: 10px;
  font-style: italic;
  padding: 4px 0;
}
