
.group-chat {
  padding: 12px;
}

.list-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--phone-border);
}
.header-icon {
  font-size: 16px;
}
.header-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--phone-text);
  flex: 1;
}
.group-count {
  font-size: 10px;
  color: var(--phone-text-dim);
  padding: 2px 8px;
  background: var(--phone-card);
  border-radius: 8px;
}

.group-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
  cursor: pointer;
  transition: all 0.2s;
  margin-bottom: 6px;
  &:hover {
    border-color: var(--phone-accent);
    transform: translateX(4px);
  }
}
.group-avatar {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: linear-gradient(135deg, #1a4a8a, #102d55);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}
.group-info {
  flex: 1;
  min-width: 0;
}
.group-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--phone-text);
}
.group-preview {
  font-size: 10px;
  color: var(--phone-text-muted);
  margin-top: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.group-arrow {
  color: var(--phone-text-muted);
  font-size: 18px;
  flex-shrink: 0;
}

// 添加群聊
.add-group-section {
  margin-top: 10px;
}
.add-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 12px;
  background: var(--phone-bg);
  border: 1px dashed var(--phone-border);
  border-radius: var(--phone-radius);
  cursor: pointer;
  color: var(--phone-text-dim);
  font-size: 12px;
  &:hover {
    border-color: var(--phone-accent);
    color: var(--phone-accent);
  }
}
.add-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
}
.add-input {
  width: 100%;
  padding: 8px 10px;
  background: var(--phone-bg);
  border: 1px solid var(--phone-border);
  border-radius: 6px;
  color: var(--phone-text);
  font-size: 12px;
  font-family: inherit;
  outline: none;
  &:focus {
    border-color: var(--phone-accent);
  }
  &::placeholder {
    color: var(--phone-text-muted);
  }
}
.add-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}
.action-btn {
  padding: 6px 14px;
  border: none;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  &.cancel {
    background: var(--phone-border);
    color: var(--phone-text-dim);
  }
  &.confirm {
    background: var(--phone-accent);
    color: var(--phone-bg);
    &:disabled {
      opacity: 0.4;
      cursor: not-allowed;
    }
  }
}

// 全局待发送
.pending-global {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px;
  margin-top: 10px;
  background: rgba(255, 165, 2, 0.1);
  border: 1px solid rgba(255, 165, 2, 0.3);
  border-radius: var(--phone-radius);
  font-size: 11px;
  color: var(--phone-warning);
  button {
    margin-left: auto;
    padding: 3px 8px;
    background: transparent;
    border: 1px solid var(--phone-warning);
    border-radius: 4px;
    color: var(--phone-warning);
    font-size: 9px;
    cursor: pointer;
    font-weight: 600;
  }
}

// 群详情
.detail-header-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px;
  margin-bottom: 12px;
  cursor: pointer;
  color: var(--phone-accent);
  &:hover {
    color: var(--phone-text);
  }
}
.back-icon {
  font-size: 20px;
}
.detail-title {
  font-size: 14px;
  font-weight: 700;
}

.setting-card {
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
  padding: 10px 12px;
  margin-bottom: 8px;
}
.setting-label {
  font-size: 10px;
  color: var(--phone-text-muted);
  font-weight: 600;
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 4px;
}
.setting-value {
  font-size: 12px;
  color: var(--phone-text);
  line-height: 1.5;
}

// 聊天记录
.chat-history {
  margin-bottom: 12px;
}
.history-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--phone-text);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.history-count {
  margin-left: auto;
  font-size: 9px;
  color: var(--phone-text-muted);
  padding: 1px 6px;
  background: var(--phone-bg);
  border-radius: 6px;
}
.history-list {
  max-height: 200px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-right: 4px;
}
.history-msg {
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--phone-bg);
  border: 1px solid var(--phone-border);
  &.msg-self {
    border-color: var(--phone-accent-dim);
    background: rgba(0, 212, 170, 0.05);
  }
}
.msg-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2px;
}
.msg-sender {
  font-size: 10px;
  font-weight: 600;
  color: var(--phone-accent);
}
.msg-self .msg-sender {
  color: var(--phone-text);
}
.msg-time {
  font-size: 9px;
  color: var(--phone-text-muted);
}
.msg-body {
  font-size: 11px;
  color: var(--phone-text-dim);
  line-height: 1.5;
}
.history-empty {
  text-align: center;
  color: var(--phone-text-muted);
  font-size: 10px;
  font-style: italic;
  padding: 12px;
}

// 查看群聊按钮
.view-chat-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px;
  background: var(--phone-card);
  border: 1px solid var(--phone-accent);
  border-radius: var(--phone-radius);
  color: var(--phone-accent);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  margin-bottom: 12px;
  &:hover {
    background: var(--phone-accent);
    color: var(--phone-bg);
  }
}

// 发送区
.send-section {
  background: var(--phone-card);
  border: 1px solid var(--phone-border);
  border-radius: var(--phone-radius);
  padding: 12px;
  margin-bottom: 8px;
}
.send-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--phone-text);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.input-row {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}
.send-input {
  flex: 1;
  background: var(--phone-bg);
  border: 1px solid var(--phone-border);
  border-radius: 8px;
  padding: 8px 10px;
  color: var(--phone-text);
  font-size: 12px;
  font-family: inherit;
  resize: none;
  outline: none;
  &:focus {
    border-color: var(--phone-accent);
  }
  &::placeholder {
    color: var(--phone-text-muted);
  }
}
.send-btn {
  padding: 8px 16px;
  background: var(--phone-accent);
  color: var(--phone-bg);
  border: none;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  &:hover:not(.disabled) {
    transform: scale(1.05);
    box-shadow: var(--phone-glow);
  }
  &.disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }
}
.send-hint {
  margin-top: 6px;
  font-size: 9px;
  color: var(--phone-text-muted);
  font-style: italic;
}

// 待发送提示
.pending-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  background: rgba(255, 165, 2, 0.1);
  border: 1px solid rgba(255, 165, 2, 0.3);
  border-radius: var(--phone-radius);
}
.pending-icon {
  font-size: 14px;
}
.pending-text {
  flex: 1;
  font-size: 10px;
  color: var(--phone-warning);
  font-weight: 600;
}
.pending-clear {
  padding: 3px 8px;
  background: transparent;
  border: 1px solid var(--phone-warning);
  border-radius: 4px;
  color: var(--phone-warning);
  font-size: 9px;
  cursor: pointer;
  font-weight: 600;
  &:hover {
    background: rgba(255, 165, 2, 0.15);
  }
}
